// Holds the signed-in session and live data from the SharedBank Worker.
//
// IMPORTANT: the Worker calls below (sign-in, dashboard, transfers, directory) and the
// idempotency-key logic in send() are moved here unchanged from the original
// LiveBank.jsx generated by the SharedBank patch. Do not change paths, headers or the
// key derivation: every bank in the network relies on the Worker contract.
import { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';
import { configuredEndpoint, liveApi, readStorage, saveStorage } from '../live-api';

const BankContext = createContext(null);
const emptyData = { accounts: [], transfers: [] };

export function BankProvider({ bank, children }) {
  const base = configuredEndpoint;
  const prefix = '/banks/' + bank.id;
  const [session, setSession] = useState(null);
  const [data, setData] = useState(emptyData);
  const [directory, setDirectory] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState('');
  const [lastUpdated, setLastUpdated] = useState(null);
  const activeToken = useRef(null);
  activeToken.current = session?.token;
  const pending = useRef(new Map());

  const logout = useCallback(() => {
    setSession(null);
    setLoaded(false);
    setData(emptyData);
    setError('');
  }, []);

  const refresh = useCallback(async signal => {
    if (!session) return;
    try {
      const value = await liveApi(base, prefix + '/dashboard', { token: session.token, signal });
      if (signal?.aborted || activeToken.current !== session.token) return;
      setData({ accounts: value.accounts || [], transfers: value.transfers || [] });
      setLoaded(true);
      setError('');
      setLastUpdated(new Date());
    } catch (failure) {
      if (signal?.aborted || activeToken.current !== session.token) return;
      if (failure.status === 401) {
        setSession(null);
        setData(emptyData);
        setLoaded(false);
      }
      setError(failure.message);
    }
  }, [base, prefix, session]);

  // Same 12-second polling as the original portal, paused while the tab is hidden.
  useEffect(() => {
    if (!session) return undefined;
    const controller = new AbortController();
    const update = () => { if (document.visibilityState === 'visible') refresh(controller.signal); };
    refresh(controller.signal);
    const timer = setInterval(update, 12_000);
    document.addEventListener('visibilitychange', update);
    return () => {
      clearInterval(timer);
      controller.abort();
      document.removeEventListener('visibilitychange', update);
    };
  }, [session, refresh]);

  useEffect(() => {
    if (!session) return undefined;
    const controller = new AbortController();
    liveApi(base, '/directory/banks', { signal: controller.signal })
      .then(value => setDirectory(value.banks || []))
      .catch(failure => { if (!controller.signal.aborted) setError(failure.message); });
    return () => controller.abort();
  }, [base, session]);

  async function signIn(email, password) {
    const value = await liveApi(base, prefix + '/sign-in', { data: { email: email.trim(), password } });
    setSession(value);
    return value;
  }

  // Unchanged from LiveBank.jsx: the same transfer details always reuse the same
  // Idempotency-Key until the Worker answers, so a retry or double click never sends twice.
  async function send(transfer) {
    const raw = JSON.stringify([bank.id, base, session.uid, transfer]);
    const bytes = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(raw)));
    const hash = Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('');
    const keyName = 'x42-pending-' + hash;
    const key = pending.current.get(keyName) || readStorage(sessionStorage, keyName, null) || crypto.randomUUID();
    pending.current.set(keyName, key);
    saveStorage(sessionStorage, keyName, key);
    const row = await liveApi(base, prefix + '/transfers', { token: session.token, data: transfer, key });
    pending.current.delete(keyName);
    saveStorage(sessionStorage, keyName, null);
    await refresh();
    return row;
  }

  const value = {
    bank, session, data, directory, loaded, error, lastUpdated,
    signIn, logout, refresh, send, clearError: () => setError(''),
  };
  return <BankContext.Provider value={value}>{children}</BankContext.Provider>;
}

export function useBank() {
  const value = useContext(BankContext);
  if (!value) throw new Error('useBank must be used inside BankProvider');
  return value;
}
